## Method and reasoning
Sort the values, preserving multiplicities. If a pair is too small, advance the left pointer. If too large, retreat the right pointer. For a match between different values multiply the two run lengths. If both ends are equal, all remaining pairs match. Fix each possible first index and apply this count to its suffix. Each sorted index triple has one first index.

## Walk through the sample
Fix the only 0 as the first value. Each of two 1s can pair with either of two 2s, giving four triples. Fixing a later first index adds none; suffix-only counting guarantees each index triple is visited once.

## Complexity
Time O(n²), space O(n) including input.

## Reference implementation
~~~
#include <bits/stdc++.h>
using namespace std;

long long pairs(const vector<int> &a, int l, long long target) {
    long long answer = 0;
    int r = int(a.size()) - 1;
    while (l < r) {
        long long sum = (long long)a[l] + a[r];
        if (sum < target)
            ++l;
        else if (sum > target)
            --r;
        else if (a[l] == a[r]) {
            long long count = r - l + 1;
            return answer + count * (count - 1) / 2;
        } else {
            int left = a[l], right = a[r], lc = 0, rc = 0;
            while (l <= r && a[l] == left) {
                ++l;
                ++lc;
            }
            while (r >= l && a[r] == right) {
                --r;
                ++rc;
            }
            answer += (long long)lc * rc;
        }
    }
    return answer;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long k;
    cin >> n >> k;
    vector<int> a(n);
    for (int &x : a)
        cin >> x;
    sort(a.begin(), a.end());
    long long answer = 0;
    for (int i = 0; i + 2 < n; ++i)
        answer += pairs(a, i + 1, k - a[i]);
    cout << answer << '\n';
}
